examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    Row(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        verticalAlignment = Alignment.Top,
    ) {
        Column(
            modifier = Modifier.weight(1f),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        ) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchText(
                    text = {{title}},
                    style = MonarchTextStyle.Title,
                    modifier = Modifier.semantics { heading() },
                )
                MonarchStatusBadge(definition = MonarchStatusDefinition(label = {{status.label}}, tone = {{status.tone|tone}}))
            }
            MonarchText(text = {{subtitle}}, style = MonarchTextStyle.Caption)
        }
        MonarchButton(
            text = {{action}},
            onClick = {},
            variant = MonarchButtonVariant.Secondary,
            size = MonarchButtonSize.Sm,
        )
    }
    MonarchKeyValue(
        items = listOf(
            MonarchKeyValueItem({{facts.0.term}}, {{facts.0.value}}),
            MonarchKeyValueItem({{facts.1.term}}, {{facts.1.value}}),
        ),
    )
    MonarchTabs(selectedIndex = currentTab, onSelectedIndexChange = { currentTab = it }) {
        tab({{tabs.0.label}})
        tab({{tabs.1.label}}, count = {{tabs.1.count}}.toString())
        tab({{tabs.2.label}})
    }
    when (tabValues[currentTab]) {
        tabValues[0] -> MonarchText(text = {{tabs.0.content}})
        tabValues[1] -> MonarchText(text = {{tabs.1.content}})
        else -> MonarchText(text = {{tabs.2.content}})
    }
    MonarchText(text = {{aside}})
    MonarchText(
        text = "Activity",
        style = MonarchTextStyle.Heading,
        modifier = Modifier.semantics { heading() },
    )
    MonarchText(text = {{activity}})
}

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    Row(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        verticalAlignment = Alignment.Top,
    ) {
        Column(
            modifier = Modifier.weight(1f),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        ) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchText(
                    text = "Sample record",
                    style = MonarchTextStyle.Title,
                    modifier = Modifier.semantics { heading() },
                )
                MonarchStatusBadge(definition = MonarchStatusDefinition(label = "Active", tone = MonarchTone.Success))
            }
            MonarchText(text = "REC-0001", style = MonarchTextStyle.Caption)
        }
        MonarchButton(
            text = "Edit",
            onClick = {},
            variant = MonarchButtonVariant.Secondary,
            size = MonarchButtonSize.Sm,
        )
    }
    MonarchKeyValue(
        items = listOf(
            MonarchKeyValueItem("Owner", "Person A"),
            MonarchKeyValueItem("Created", "1 June 2026"),
        ),
    )
    MonarchTabs(selectedIndex = currentTab, onSelectedIndexChange = { currentTab = it }) {
        tab("Overview")
        tab("Notes", count = 2.toString())
        tab("Files")
    }
    when (tabValues[currentTab]) {
        tabValues[0] -> MonarchText(text = "Overview content for the sample record.")
        tabValues[1] -> MonarchText(text = "Two sample notes.")
        else -> MonarchText(text = "No files yet.")
    }
    MonarchText(text = "Properties and related records go here.")
    MonarchText(
        text = "Activity",
        style = MonarchTextStyle.Heading,
        modifier = Modifier.semantics { heading() },
    )
    MonarchText(text = "Sample activity entries go here.")
}
